import{_ as t,o,c as a,a4 as s}from"./chunks/framework.Dsbb2oA0.js";const h=JSON.parse('{"title":"Deployment and Startup Notes (MxServiceCode / MxCAD Conversion Program)","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/9.AIManual/4.BackendReferenceDocs/3.DeploymentAndStartup.md","filePath":"en/docs/9.AIManual/4.BackendReferenceDocs/3.DeploymentAndStartup.md"}'),n={name:"en/docs/9.AIManual/4.BackendReferenceDocs/3.DeploymentAndStartup.md"};function i(r,e,d,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="deployment-and-startup-notes-mxservicecode-mxcad-conversion-program" tabindex="-1">Deployment and Startup Notes (MxServiceCode / MxCAD Conversion Program) <a class="header-anchor" href="#deployment-and-startup-notes-mxservicecode-mxcad-conversion-program" aria-label="Permalink to &quot;Deployment and Startup Notes (MxServiceCode / MxCAD Conversion Program)&quot;">​</a></h1><blockquote><p>Compiled from the actual installation package layout and startup scripts.</p></blockquote><h2 id="i-program-location-fixed-temp-path" tabindex="-1">I. Program Location (Fixed Temp Path) <a class="header-anchor" href="#i-program-location-fixed-temp-path" aria-label="Permalink to &quot;I. Program Location (Fixed Temp Path)&quot;">​</a></h2><p>Two kinds of packages: <strong>standalone conversion program</strong> (MxConvert, mxcadassembly only) and <strong>backend service</strong> (MxServiceCode, contains BOTH the backend service and the conversion program — the complete superset). Download URLs: follow the &quot;Link List&quot; in the <a href="./../1.EntryGuide.html">Entry Guide</a> (take the row matching the need + platform; the Linux package is built for Ubuntu 20.04 x86_64).</p><p><strong>Fixed temp path (download once, reuse across sessions; after the system cleans the temp dir, just re-download)</strong>:</p><ul><li>Windows: <code>%TEMP%\\MxCAD\\</code> (<code>%TEMP%</code> is the user&#39;s Temp directory environment variable; use it as-is in commands, no manual expansion needed)</li><li>Linux: <code>/tmp/MxCAD/</code></li></ul><p>Follow the check steps in the <a href="./../1.EntryGuide.html">Entry Guide</a>: first determine what the task needs, then inspect what is in the temp path — nothing there → download the matching zip per need (conversion program only → standalone MxConvert package; backend service needed → MxServiceCode package, which includes the conversion program) and extract it to the temp path; conversion program only present → if only the conversion program is needed, run &quot;III. Trial Version Expiry Check&quot; first and it is ready to use; if the backend is needed, clear and re-download the backend package; backend package already extracted → run the expiry check + integrity verification, and if incomplete, clear and re-download. <strong>The temp path MUST be cleared before any re-download (each package has a fixed structure; the backend package is the complete superset). Do not scan other directories on the user&#39;s machine.</strong></p><h3 id="after-extraction-windows-a-single-top-level-dir-mxservicecode-tryversion-same-name-as-the-zip" tabindex="-1">After extraction (Windows: a single top-level dir <code>MxServiceCode_TryVersion\\</code>, same name as the zip) <a class="header-anchor" href="#after-extraction-windows-a-single-top-level-dir-mxservicecode-tryversion-same-name-as-the-zip" aria-label="Permalink to &quot;After extraction (Windows: a single top-level dir \`MxServiceCode_TryVersion\\\`, same name as the zip)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxServiceCode_TryVersion\\    ← Top-level dir after extraction (same name as the zip)</span></span>
<span class="line"><span>├── MxServiceCode\\</span></span>
<span class="line"><span>│   ├── NODE.JS后台程序开发.doc   ← Official backend development tutorial (not an API doc)</span></span>
<span class="line"><span>│   ├── MxServiceCode.sln        ← Solution file</span></span>
<span class="line"><span>│   └── MxServiceCode\\           ← Project directory (the commands below run here)</span></span>
<span class="line"><span>│       ├── bin\\node.exe          ← Built-in Node runtime</span></span>
<span class="line"><span>│       ├── mxapp.js              ← Entry point (command line)</span></span>
<span class="line"><span>│       ├── src\\                  ← TS sources (mxcad\\ = API classes, sample\\ = examples, MxCommand.ts = command registration)</span></span>
<span class="line"><span>│       ├── Mx2DNode.node         ← Native module</span></span>
<span class="line"><span>│       ├── package.json          ← npm run build for compilation</span></span>
<span class="line"><span>│       ├── test.bat              ← Test script</span></span>
<span class="line"><span>│       ├── empty_template.dwg    ← Blank template</span></span>
<span class="line"><span>│       ├── A3.dwg / BT.DWG       ← Title block frame / title block sample blocks</span></span>
<span class="line"><span>│       └── t1.dwg / tree.dwg     ← Test drawings</span></span>
<span class="line"><span>└── MxCAD\\</span></span>
<span class="line"><span>    └── Release\\                 ← Format conversion program directory (mxcadassembly.exe + runtime dependency dlls + mxcad_ini.json, mxcode.bin, mxiconv.data + **fonts\\** + files\\)</span></span></code></pre></div><h3 id="after-extraction-linux-a-single-top-level-dir-mxservicecode-tryversion-same-name-as-the-zip" tabindex="-1">After extraction (Linux: a single top-level dir <code>MxServiceCode_TryVersion\\</code>, same name as the zip) <a class="header-anchor" href="#after-extraction-linux-a-single-top-level-dir-mxservicecode-tryversion-same-name-as-the-zip" aria-label="Permalink to &quot;After extraction (Linux: a single top-level dir \`MxServiceCode_TryVersion\\\`, same name as the zip)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxServiceCode_TryVersion\\    ← Top-level dir after extraction (same name as the zip)</span></span>
<span class="line"><span>├── MxServiceCode\\</span></span>
<span class="line"><span>│   ├── NODE.JS后台程序开发.doc   ← Official backend development tutorial</span></span>
<span class="line"><span>│   └── MxServiceCode\\           ← Project directory (no .sln; the built-in runtime is \`node\`, not bin\\node.exe;</span></span>
<span class="line"><span>│                                 also contains start_demo_MxServiceCode.sh, start_demo_systemlib_MxServiceCode.sh, Linux启动说明.txt)</span></span>
<span class="line"><span>└── Linux\\</span></span>
<span class="line"><span>    └── MxCAD\\                   ← Format conversion program directory (mxcadassembly + runtime dependencies mx/so + mxcad_ini.json, mxcode.bin, mxiconv.data + **fonts\\** + files\\)</span></span></code></pre></div><blockquote><p><strong>Conversion program directory</strong> = <code>MxServiceCode_TryVersion\\MxCAD\\Release\\</code> under the Windows temp path, <code>MxServiceCode_TryVersion\\Linux\\MxCAD\\</code> under the Linux temp path (or <code>MxConvert_TryVersion\\</code> itself for the standalone MxConvert package); <strong>fonts needed for frontend drawing preview = the <code>fonts\\</code> directory inside it</strong> (just copy it).</p></blockquote><h2 id="ii-running-mxservicecode-commands-no-service-to-start" tabindex="-1">II. Running MxServiceCode Commands (no service to start) <a class="header-anchor" href="#ii-running-mxservicecode-commands-no-service-to-start" aria-label="Permalink to &quot;II. Running MxServiceCode Commands (no service to start)&quot;">​</a></h2><p>Command mode is a standalone process; call the built-in node directly:</p><p><strong>Windows</strong> (in the project directory):</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bin\\node.exe mxapp.js getcaddata file=t1.dwg outfile=t1.dwg.json</span></span></code></pre></div><p><strong>Linux</strong> (in the project directory):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mxapp.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> getcaddata</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file=t1.dwg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> outfile=t1.dwg.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><p>Running <code>node mxapp.js</code> with no arguments prints version info and the log path.</p><blockquote><p>⚠️ <strong>Built-in Node version limitation (tested)</strong>: <code>bin\\node.exe</code> is <strong>v10.9.0</strong> and supports <strong>CommonJS only</strong> — ESM (<code>import</code> syntax / <code>.mjs</code>) throws <code>SyntaxError</code> directly; there is no <code>fetch</code>, no optional chaining, or other newer features. Helper scripts written for the built-in node must use CommonJS (<code>require</code>) + <code>.js</code>; when you need ESM, use the system Node.</p></blockquote><h3 id="linux-first-deployment-permission-setup" tabindex="-1">Linux First Deployment (permission setup) <a class="header-anchor" href="#linux-first-deployment-permission-setup" aria-label="Permalink to &quot;Linux First Deployment (permission setup)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 777</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_demo_MxServiceCode.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start_demo_MxServiceCode.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # the script already chmods mxcadassembly, mx/so, Mx2DNode.node, node</span></span></code></pre></div><p>If it fails, use <code>./start_demo_systemlib_MxServiceCode.sh</code> instead (uses the native libraries in the systemLib directory).</p><h2 id="iii-format-conversion-program-mxcadassembly-standalone-invocation" tabindex="-1">III. Format Conversion Program mxcadassembly (standalone invocation) <a class="header-anchor" href="#iii-format-conversion-program-mxcadassembly-standalone-invocation" aria-label="Permalink to &quot;III. Format Conversion Program mxcadassembly (standalone invocation)&quot;">​</a></h2><p><strong>Windows</strong> (in the conversion program directory; the two forms are equivalent — pick by shell):</p><ul><li>cmd / PowerShell (bare JSON, the official-docs form, no encoding needed):</li></ul><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mxcadassembly.exe {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;srcpath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.dwg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;outname&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;_trial.mxweb&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;outpath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./out&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li>Git Bash (percent-encoded string in quotes; bare JSON returns <code>read file error</code> in this shell, tested):</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>mxcadassembly.exe &quot;[%7B%22srcpath%22%3A%221.dwg%22%2C%22outname%22%3A%22_trial.mxweb%22%2C%22outpath%22%3A%22.%2Fout%22%7D]&quot;</span></span></code></pre></div><p><strong>Linux</strong> (in the conversion program directory; bare JSON in single quotes):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 777</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mxcadassembly</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./mx/so/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./mxcadassembly</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;srcpath&quot;:&quot;1.dwg&quot;,&quot;outname&quot;:&quot;_trial.mxweb&quot;,&quot;outpath&quot;:&quot;./out&quot;}&#39;</span></span></code></pre></div><p>(Equivalent alternative: <code>./mxcadassembly &#39;[%7B%22srcpath%22%3A%221.dwg%22%2C%22outname%22%3A%22_trial.mxweb%22%2C%22outpath%22%3A%22.%2Fout%22%7D]&#39;</code>)</p><blockquote><p>Parameter form convention: the program accepts two equivalent forms — ① <strong>bare JSON</strong> (the official-docs form; works directly in cmd / PowerShell / Linux bash; in bash wrap it in single quotes); ② <strong>percent-hex-encoded string wrapped in square brackets</strong> (e.g. <code>{&quot;a&quot;:1}</code> → <code>[%7B%22a%22%3A1%7D]</code>; used internally by MxServiceCode; required in Git Bash). <code>MxUtility.callMxCadAssembly</code> inside MxServiceCode already encapsulates this logic — <strong>in secondary development, prefer calling through the TS API; do not hand-build the command</strong>.</p></blockquote><blockquote><p>⚠️ <strong>Common pitfalls (tested)</strong></p><ul><li>The encoding MUST include the <code>%</code> prefix; plain hex (e.g. <code>7b2261223a317d</code>) returns <code>{&quot;code&quot;:1,&quot;message&quot;:&quot;read file error&quot;}</code></li><li><strong>In cmd.exe / batch files, <code>%</code> is a batch-variable reference</strong>: a percent-encoded string gets mangled by expansion (returns <code>{&quot;code&quot;:1,&quot;message&quot;:&quot;read file error&quot;}</code>) — use the bare-JSON form in cmd</li><li>On Windows, <code>python</code> may be a Store placeholder program (silently no output); use the built-in <code>bin\\node.exe</code> for temp scripts that generate encoded parameters</li><li>When the <code>convert</code> command is unusable (wgh deprecated; see &quot;MxServiceCodeCommandReference.md&quot; detailed 1), <strong>this standalone invocation is the only way to do DWG→mxweb</strong>; the mxcad frontend only accepts mxweb</li></ul></blockquote><h3 id="trial-version-expiry-check" tabindex="-1">Trial Version Expiry Check <a class="header-anchor" href="#trial-version-expiry-check" aria-label="Permalink to &quot;Trial Version Expiry Check&quot;">​</a></h3><blockquote><p>The conversion program is a <strong>trial version, valid for 6 months</strong>. If the conversion program is already in the temp path, you MUST run a <strong>test conversion</strong> before use (command-line mode, no GUI; run in the conversion program directory, using a bundled test drawing such as <code>1.dwg</code>, with the output directory created first):</p><p>Windows (cmd / PowerShell): <code>mxcadassembly.exe {&quot;srcpath&quot;:&quot;1.dwg&quot;,&quot;outname&quot;:&quot;_trial.mxweb&quot;,&quot;outpath&quot;:&quot;./out&quot;}</code>; Windows (Git Bash): <code>mxcadassembly.exe &quot;[%7B%22srcpath%22%3A%221.dwg%22%2C%22outname%22%3A%22_trial.mxweb%22%2C%22outpath%22%3A%22.%2Fout%22%7D]&quot;</code>; Linux: <code>./mxcadassembly &#39;{&quot;srcpath&quot;:&quot;1.dwg&quot;,&quot;outname&quot;:&quot;_trial.mxweb&quot;,&quot;outpath&quot;:&quot;./out&quot;}&#39;</code></p></blockquote><ul><li>Returns <code>{&quot;code&quot;:0,&quot;message&quot;:&quot;ok&quot;}</code> → valid and usable; use it directly.</li><li>Returns non-zero → read the version string in <code>%TEMP%\\MxNode\\mxcad_*.log</code> (recorded on every run; tested sample format: <code>MxCAD TryVersion:7.0(2026-10-21 11:16)(64bit)(cooperate)</code>): <ul><li><strong>The date in parentheses (e.g. <code>2026-10-21</code>) = the trial start date</strong>; <code>current date − trial start date &gt; 5 months</code> → expired; re-download the zip and extract over the temp path (URL in the Entry Guide &quot;Link List&quot;)</li><li>Not expired → program environment problem; debug according to the log</li></ul></li></ul><p>Common JSON parameters (see the official &quot;Drawing Conversion Details&quot; for the full list):</p><ul><li>Convert: <code>{&quot;srcpath&quot;:&quot;a.dwg&quot;,&quot;outname&quot;:&quot;a.mxweb&quot;,&quot;outpath&quot;:&quot;./out&quot;}</code> (paths relative to the conversion program directory; the outname extension decides the target format; mxweb→dwg must explicitly carry .dwg/.dxf; the <code>outpath</code> directory must pre-exist)</li><li>Crop DWG: <code>{&quot;cmd&quot;:&quot;cut_dwg&quot;,&quot;bd_pt1_x&quot;:0,&quot;bd_pt1_y&quot;:0,&quot;bd_pt2_x&quot;:100,&quot;bd_pt2_y&quot;:100,&quot;srcpath&quot;:&quot;a.dwg&quot;,&quot;outname&quot;:&quot;cut.dwg&quot;}</code></li><li>Output PDF: <code>{&quot;srcpath&quot;:&quot;a.dwg&quot;,&quot;outname&quot;:&quot;a.pdf&quot;,&quot;outpath&quot;:&quot;./out&quot;,&quot;ret_page_extents&quot;:true,&quot;width&quot;:&quot;2000&quot;,&quot;height&quot;:&quot;2000&quot;,&quot;colorPolicy&quot;:&quot;mono&quot;}</code> — <strong>no <code>cmd</code> field</strong> (including it returns <code>{&quot;code&quot;:201}</code>); output location follows the same rules as other conversions: the output directory is <code>outpath</code> (falls back to the conversion program directory when omitted), the file name is <code>outname</code> (when <code>outname</code> is an absolute path, write directly to that location)</li><li><code>srcpath</code>/<code>outpath</code>/<code>outname</code> all support absolute paths (including Chinese paths)</li><li>⚠️ <strong>Artifacts of real tasks MUST be written to the location the user asked for</strong> (absolute path or a path relative to the user&#39;s workspace); do NOT leave them in the conversion program directory&#39;s <code>out/</code>: the temp path is wiped (before re-download / by system cleanup) and anything left there (mxweb / pdf / images) is lost; <code>./out</code> is only for the trial check</li><li>⚠️ The <code>cmd</code> parameter domain (such as <code>print_to_pdf</code>) belongs to the MxServiceCode backend service interface; for direct mxcadassembly.exe calls only the parameters above are valid</li><li>If mxcadassembly is a <strong>runtime dependency of a user feature</strong> (e.g. an &quot;upload and open drawings online&quot; feature), note that the temp path is unstable (wiped before switching packages / auto-cleaned by the OS); see the &quot;Runtime-conversion features&quot; note at the end of section 1.1 in &quot;Frontend mxcad Guide&quot; for how to handle it</li></ul><h2 id="iv-secondary-development-workflow" tabindex="-1">IV. Secondary Development Workflow <a class="header-anchor" href="#iv-secondary-development-workflow" aria-label="Permalink to &quot;IV. Secondary Development Workflow&quot;">​</a></h2><ol><li>Modify <code>src/sample/*.ts</code> or add a new file (API in &quot;Mx2DNodeSecondaryDevAPIReference.md&quot;)</li><li>Register the command in <code>src/MxCommand.ts</code> (see &quot;MxServiceCodeCommandReference.md&quot; section 6)</li><li>Compile: <code>npm run build</code> (node_modules is bundled; if missing, use <code>bin\\node.exe node_modules\\typescript\\bin\\tsc --build</code>)</li><li>Verify with <code>bin\\node.exe mxapp.js &lt;command&gt; param=value debug=1</code></li></ol><h2 id="v-logs" tabindex="-1">V. Logs <a class="header-anchor" href="#v-logs" aria-label="Permalink to &quot;V. Logs&quot;">​</a></h2><ul><li>Path: <code>%TEMP%\\MxNode</code> (same convention on Linux)</li><li>Each command ends by printing <code>logs end</code>; with <code>debug=1</code> the log is more detailed</li><li>When the return is <code>{&quot;code&quot;:-4,&quot;message&quot;:&quot;js program exception, see log for details&quot;}</code>, check the log file</li></ul><h2 id="vi-bundled-resources" tabindex="-1">VI. Bundled Resources <a class="header-anchor" href="#vi-bundled-resources" aria-label="Permalink to &quot;VI. Bundled Resources&quot;">​</a></h2><table><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>empty_template.dwg</code></td><td>Blank template; <code>Mx2DDraw.getEmptyTemplateDwgFilePath()</code> points to it</td></tr><tr><td><code>A3.dwg</code> / <code>BT.DWG</code></td><td>Title block frame / title block samples (the BT block contains attribute definitions); used by testParamDrawTk</td></tr><tr><td><code>t1.dwg</code> / <code>tree.dwg</code></td><td>Test drawing / test block (the tree block is used by testParamDraw)</td></tr><tr><td><code>mxcad_ini.json</code> (in the conversion program directory)</td><td>Conversion program config (font paths, etc.); do not modify casually</td></tr><tr><td><code>fonts\\</code></td><td>Font directory (SHX/TTF font dependencies of DWGs)</td></tr></tbody></table>`,45)])])}const m=t(n,[["render",i]]);export{h as __pageData,m as default};
